import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"算子包部署时出现权限不足报错","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子包部署时出现权限不足报错","slug":"算子包部署时出现权限不足报错"},{"level":2,"title":"现象描述","slug":"现象描述"},{"level":2,"title":"问题根因","slug":"问题根因"},{"level":2,"title":"处理步骤","slug":"处理步骤"}],"relativePath":"guide/编程指南/附录/FAQ/算子包部署时出现权限不足报错.md","filePath":"guide/编程指南/附录/FAQ/算子包部署时出现权限不足报错.md"}'),l={name:"guide/编程指南/附录/FAQ/算子包部署时出现权限不足报错.md"};function i(o,a,p,r,c,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="算子包部署时出现权限不足报错" tabindex="-1">算子包部署时出现权限不足报错 <a class="header-anchor" href="#算子包部署时出现权限不足报错" aria-label="Permalink to &quot;算子包部署时出现权限不足报错&quot;">​</a></h1><h2 id="现象描述" tabindex="-1">现象描述 <a class="header-anchor" href="#现象描述" aria-label="Permalink to &quot;现象描述&quot;">​</a></h2><p>部署自定义算子包时，出现如下报错信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] The directory /usr/local/Ascend/cann/opp does not have sufficient permissions. Please check and modify the folder permissions (e.g., using chmod), or use the --install-path option to specify an installation path and change the environment variable ASCEND_CUSTOM_OPP_PATH to the specified path.</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[ERROR] create /usr/local/Ascend/cann/opp/vendors/customize/framework failed</span></span></code></pre></div><h2 id="问题根因" tabindex="-1">问题根因 <a class="header-anchor" href="#问题根因" aria-label="Permalink to &quot;问题根因&quot;">​</a></h2><p>当前操作用户缺少对部署路径下vendors目录的写权限。</p><p>自定义算子包默认安装路径\${INSTALL_DIR}/opp/vendors的目录权限与CANN软件包安装用户和安装配置有关：root用户安装CANN，\${INSTALL_DIR}/opp/vendors权限为755；非root用户携带--install for all参数安装CANN，该目录权限为755，非root用户不带--install for all参数安装CANN时，该目录权限为750。</p><p>例如，root用户安装CANN软件包后，HwHiAiUser属组用户在对应目录部署自定义算子包，因为其他用户没有写权限，会出现上述报错信息，提示权限不足导致自定义算子包部署失败。</p><h2 id="处理步骤" tabindex="-1">处理步骤 <a class="header-anchor" href="#处理步骤" aria-label="Permalink to &quot;处理步骤&quot;">​</a></h2><ul><li><p>方法一：使用--install-path参数并配置环境变量ASCEND_CUSTOM_OPP_PATH来指定安装目录（参考<a href="./../../高级编程/高级特性/Aclnn算子工程化开发/算子包编译/算子包部署.html#li1652971821912">指定目录安装</a>）。运行用户需要对指定的安装路径有可读写权限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./custom_opp_&lt;target os&gt;_&lt;target architecture&gt;.run --install-path=&lt;path&gt;</span></span>
<span class="line"><span>source &lt;path&gt;/vendors/&lt;vendor_name&gt;/bin/set_env.bash</span></span></code></pre></div></li><li><p>方法二：联系CANN软件包安装用户修改默认安装路径下的vendors目录权限，比如修改为777：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 777 /usr/local/Ascend/cann/opp/vendors/</span></span></code></pre></div></li></ul>`,10)])])}const _=e(l,[["render",i]]);export{u as __pageData,_ as default};
